import { Fragment, useEffect } from "react";
import Breadcrumbs from "@components/breadcrumbs";
import {
  Card,
  CardFooter,
  Button,
  CardBody,
  Row,
  Col,
  Label,
  Input,
  FormFeedback,
} from "reactstrap";
import { useNavigate, useSearchParams } from "react-router-dom";
import useRate from "../../../hooks/use_rate";
import toast from "react-hot-toast";
import ProgressLoading from "../../../components/progress_loading";

const UpdateRate = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { getRateById, updateRateController, rateLoadings } = useRate();

  useEffect(() => {
    let rate_id = searchParams.get("rate_id");
    if (rate_id) {
      getRateById(rate_id);
    } else {
      navigate("/rates/all");
      toast.error("Rate not found!");
    }
  }, []);

  return (
    <Fragment>
      <Breadcrumbs
        title="Update Rate"
        data={[{ title: "Rates" }, { title: "Update Rate" }]}
      />
      {rateLoadings.getRateById ? (
        <ProgressLoading />
      ) : (
        <form onSubmit={updateRateController.handleSubmit}>
          <Card>
            <CardBody>
              <Row>
                <Col className="mt-1" xs="12" sm="6" md="4">
                  <Label for="monetary_unit">monetary_unit</Label>
                  <Input
                    value={updateRateController.values.monetary_unit}
                    onChange={updateRateController.handleChange}
                    invalid={
                      updateRateController.touched.monetary_unit
                        ? updateRateController.errors.monetary_unit
                        : null
                    }
                    name="monetary_unit"
                    id="monetary_unit"
                  />
                  {updateRateController?.errors?.monetary_unit && (
                    <FormFeedback>
                      {updateRateController.errors.monetary_unit}
                    </FormFeedback>
                  )}
                </Col>
                <Col className="mt-1" xs="12" sm="6" md="4">
                  <Label for="non_monetary_unit">non_monetary_unit</Label>
                  <Input
                    value={updateRateController.values.non_monetary_unit}
                    onChange={updateRateController.handleChange}
                    invalid={
                      updateRateController.touched.non_monetary_unit
                        ? updateRateController.errors.non_monetary_unit
                        : null
                    }
                    name="non_monetary_unit"
                    id="non_monetary_unit"
                  />
                  {updateRateController?.errors?.non_monetary_unit && (
                    <FormFeedback>
                      {updateRateController.errors.non_monetary_unit}
                    </FormFeedback>
                  )}
                </Col>
              </Row>
            </CardBody>
            <CardFooter className="d-flex justify-content-center">
              <Button
                size="md"
                disabled={rateLoadings.updateRate}
                color={rateLoadings.updateRate ? "secondary" : "primary"}
              >
                Update
              </Button>
            </CardFooter>
          </Card>
        </form>
      )}
    </Fragment>
  );
};
export default UpdateRate;
